<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {useRoute} from 'vue-router';import {useAuth} from '../stores/auth';import {api} from '../api';import DataPanel from '../components/DataPanel.vue';
const auth=useAuth(),route=useRoute(),section=computed(()=>route.path==='/guidelines'?'guidelines':route.path==='/platform'?'platform':route.path==='/help'?'help':String(route.params.section||'organization')),data=ref<any>(),audit=ref<any[]>([]),usage=ref<any>(),error=ref(''),success=ref(''),busy=ref(false),org=ref<any>({name:'',branding:{product_name:'MortgageLens',accent:'#0f766e',logo_text:'ML'},preferences:{timezone:'America/New_York',currency:'USD'}}),profile=ref({name:auth.user.name,email:auth.user.email}),password=ref({current_password:'',password:'',password_confirmation:''}),confirmPassword=ref(''),qr=ref(''),codes=ref<string[]>([]),code=ref(''),invite=ref({email:'',role:'broker',org_wide_access:false});const admin=computed(()=>['owner','admin'].includes(auth.membership?.role));
async function load(){try{if(section.value==='organization'){data.value=await api('/api/organizations/'+auth.orgId);if(admin.value)audit.value=await api('/api/organizations/'+auth.orgId+'/audit');org.value={...org.value,...data.value.organization,branding:{...org.value.branding,...data.value.organization.branding},preferences:{...org.value.preferences,...data.value.organization.preferences}}}if(section.value==='plans'){data.value=await api('/api/plans');if(admin.value)usage.value=await api('/api/organizations/'+auth.orgId+'/usage')}if(section.value==='guidelines')data.value=await api('/api/rulesets?organization_id='+auth.orgId);if(section.value==='platform')data.value=await api('/api/platform')}catch(e:any){error.value=e.message}}onMounted(load);
async function act(fn:()=>Promise<any>,text:string){error.value='';success.value='';busy.value=true;try{await fn();success.value=text;await auth.refresh();await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function enable2fa(){await act(async()=>{await api('/api/auth/user/confirm-password','POST',{password:confirmPassword.value});await api('/api/auth/user/two-factor-authentication','POST');qr.value=(await api('/api/auth/user/two-factor-qr-code')).svg;codes.value=await api('/api/auth/user/two-factor-recovery-codes')},'Scan the QR code and confirm with your authenticator. Keep recovery codes offline.');confirmPassword.value=''}
async function recovery(){await act(async()=>{await api('/api/auth/user/confirm-password','POST',{password:confirmPassword.value});codes.value=await api('/api/auth/user/two-factor-recovery-codes')},'Recovery codes displayed only here. Do not share them.');confirmPassword.value=''}
</script>
<template><section><div class="page-heading"><div><span class="eyebrow">WORKSPACE CONTROLS</span><h1>{{section==='profile'?'My account & security':section==='organization'?'Organization settings':section==='plans'?'Plans & entitlements':section==='guidelines'?'Guidelines library':section==='platform'?'Platform administration':'Help & roadmap'}}</h1><p class="muted">Clear boundaries, thoughtful controls, secure collaboration.</p></div></div><p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="success" class="alert success" role="status">{{success}}</p>
<template v-if="section==='organization'"><div class="settings-grid"><article class="card"><h2>Branding & preferences</h2><form class="form-stack" @submit.prevent="act(()=>api('/api/organizations/'+auth.orgId,'PATCH',org),'Organization preferences updated.')"><label>Organization name<input v-model="org.name" required :disabled="!admin"/></label><label>Working product name<input v-model="org.branding.product_name" :disabled="!admin" maxlength="40"/></label><label>Brand accent<input v-model="org.branding.accent" type="color" :disabled="!admin"/></label><label>Logo initials<input v-model="org.branding.logo_text" maxlength="20" :disabled="!admin"/></label><label>Preferred timezone<input v-model="org.preferences.timezone" :disabled="!admin"/></label><p class="micro">Audit timestamps remain UTC in storage; this review environment labels displayed history in Dhaka time.</p><button v-if="admin" class="primary" :disabled="busy">Save organization</button></form></article><article class="card"><h2>Membership & invitations</h2><p class="muted">Members receive only their role's permissions. File sharing is separate.</p><form v-if="admin" class="form-stack" @submit.prevent="act(()=>api('/api/organizations/'+auth.orgId+'/invitations','POST',{...invite,org_wide_access:invite.role==='admin'&&invite.org_wide_access}),'Invitation sent using the configured mail transport.')"><label>Email<input v-model="invite.email" type="email" required/></label><label>Role<select v-model="invite.role"><option v-for="r in ['admin','underwriter','processor','broker','viewer']">{{r}}</option></select></label><label v-if="invite.role==='admin'" class="check"><input type="checkbox" v-model="invite.org_wide_access"/>Explicitly grant organization-wide file access</label><button class="primary" :disabled="busy">Invite member</button></form><div v-for="m in data?.members" class="member-row"><div><strong>{{m.user.name}}</strong><small>{{m.user.email}} · {{m.role}}{{m.org_wide_access?' · Organization-wide grant':''}}</small></div><div v-if="admin&&m.role!=='owner'&&m.user_id!==auth.user.id" class="actions"><select aria-label="Change member role" :value="m.role" @change="act(()=>api('/api/organizations/'+auth.orgId+'/members/'+m.id,'PATCH',{role:($event.target as HTMLSelectElement).value,org_wide_access:false}),'Membership role updated; file access re-evaluated immediately.')"><option v-for="r in ['admin','underwriter','processor','broker','viewer']">{{r}}</option></select><label v-if="m.role==='admin'" class="check"><input type="checkbox" :checked="m.org_wide_access" @change="act(()=>api('/api/organizations/'+auth.orgId+'/members/'+m.id,'PATCH',{role:m.role,org_wide_access:($event.target as HTMLInputElement).checked}),'Explicit organization-wide grant updated.')"/>All files</label><button @click="act(()=>api('/api/organizations/'+auth.orgId+'/members/'+m.id,'DELETE'),'Membership removed and file shares removed.')">Remove</button></div></div><div v-for="i in data?.invitations" class="member-row"><div><strong>{{i.email}}</strong><small>{{i.role}} · {{i.accepted_at?'Accepted':i.revoked_at?'Revoked':'Pending'}} · Expires {{new Date(i.expires_at).toLocaleDateString()}}</small></div><button v-if="admin&&!i.accepted_at&&!i.revoked_at" @click="act(()=>api('/api/organizations/'+auth.orgId+'/invitations/'+i.id,'DELETE'),'Invitation revoked.')">Revoke invite</button></div></article></div><article v-if="admin" class="card spaced"><h2>Organization audit history</h2><p class="micro">Organization actions and only file events covered by your file grants. Append-only history.</p><div v-for="a in audit" class="activity-row"><div><strong>{{a.action.replaceAll('.',' · ')}}</strong><small>Member {{a.actor_id||'system'}} · {{new Date(a.created_at).toLocaleString('en-US',{timeZone:'Asia/Dhaka'})}} (Dhaka){{a.loan_file_id?' · File '+a.loan_file_id:''}}</small></div></div></article></template>
<template v-else-if="section==='profile'"><div class="settings-grid"><article class="card"><h2>Profile</h2><form class="form-stack" @submit.prevent="act(()=>api('/api/auth/user/profile-information','PUT',profile),'Profile updated. A changed email requires verification.')"><label>Name<input v-model="profile.name" required/></label><label>Email<input v-model="profile.email" type="email" required/></label><button class="primary" :disabled="busy">Save profile</button></form><h2 class="spaced">Change password</h2><form class="form-stack" @submit.prevent="act(()=>api('/api/auth/user/password','PUT',password),'Password updated.')"><label>Current password<input v-model="password.current_password" type="password" autocomplete="current-password" required/></label><label>New password<input v-model="password.password" type="password" minlength="12" autocomplete="new-password" required/></label><label>Confirm new password<input v-model="password.password_confirmation" type="password" autocomplete="new-password" required/></label><button class="primary" :disabled="busy">Update password</button></form></article><article class="card"><h2>Two-factor authentication</h2><p>Authenticator TOTP with single-use recovery codes. Setup is not complete until you verify a code.</p><span class="badge" :class="auth.user.two_factor_confirmed_at?'teal':'amber'">{{auth.user.two_factor_confirmed_at?'Enabled':'Not enabled'}}</span><label class="form-stack spaced">Confirm your password<input v-model="confirmPassword" type="password" autocomplete="current-password"/></label><div class="actions spaced"><button v-if="!auth.user.two_factor_confirmed_at" class="primary" @click="enable2fa" :disabled="busy">Set up authenticator</button><button v-else @click="recovery" :disabled="busy">Show recovery codes</button><button v-if="auth.user.two_factor_confirmed_at" @click="act(async()=>{await api('/api/auth/user/confirm-password','POST',{password:confirmPassword});await api('/api/auth/user/two-factor-authentication','DELETE');qr='';codes=[];confirmPassword=''},'Two-factor authentication disabled.')">Disable 2FA</button></div><div v-if="qr" class="qr-code" v-html="qr"></div><form v-if="qr&&!auth.user.two_factor_confirmed_at" class="form-stack" @submit.prevent="act(()=>api('/api/auth/user/confirmed-two-factor-authentication','POST',{code}),'Two-factor authentication confirmed.')"><label>Six-digit authenticator code<input v-model="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" required/></label><button class="primary">Confirm setup</button></form><div v-if="codes.length" class="recovery-codes"><h3>Recovery codes — save offline</h3><code v-for="c in codes">{{c}}</code><button @click="codes=[];qr=''">Hide sensitive setup</button><button v-if="auth.user.two_factor_confirmed_at" @click="act(async()=>{await api('/api/auth/user/confirm-password','POST',{password:confirmPassword});await api('/api/auth/user/two-factor-recovery-codes','POST');codes=await api('/api/auth/user/two-factor-recovery-codes');confirmPassword=''},'Recovery codes regenerated. Previous codes are invalid.')">Regenerate codes</button></div></article></div></template>
<template v-else-if="section==='plans'"><p class="notice">{{data?.pricing_notice}}</p><p>Current plan: <strong>{{auth.org?.plan?.name}}</strong> · {{auth.org?.subscription_status}}. Limits include preserved archived files, pending invitations and every original version.</p><div v-if="usage" class="stat-grid"><article class="stat"><span>Preserved files</span><strong>{{usage.files}} / {{auth.org?.plan?.file_limit}}</strong></article><article class="stat"><span>Members + pending invitations</span><strong>{{usage.members+usage.pending_invitations}} / {{auth.org?.plan?.member_limit}}</strong></article><article class="stat"><span>Preserved storage</span><strong>{{(usage.storage_bytes/1048576).toFixed(1)}} MB</strong><small>Limit {{(auth.org?.plan?.storage_limit_bytes/1073741824).toFixed(0)}} GB</small></article></div><div class="module-grid"><article v-for="p in data?.plans" class="card"><span class="eyebrow">PROVISIONAL SAMPLE PLAN</span><h2>{{p.name}}</h2><h3>${{p.provisional_monthly_price}} / month</h3><p>{{p.file_limit}} loan files</p><p>{{p.member_limit}} organization members</p><p>{{(p.storage_limit_bytes/1073741824).toFixed(0)}} GB preserved originals</p><span class="badge">Checkout not configured</span></article></div></template>
<template v-else-if="section==='guidelines'"><div class="notice">{{data?.notice}}</div><article v-for="r in data?.rulesets" class="card"><span class="badge amber">{{r.status}}</span><h2>{{r.name}}</h2><p>Version {{r.version}} · scoped to your organization</p><DataPanel :data="r.rules"/></article><article class="card"><h2>Approved investor policy integration is pending</h2><p>Load sample analysis on a fictional file to see a versioned draft ruleset. These are not Fannie Mae or approved lender rules.</p><p>Investor definitions, NSF counting, transfer tolerance and sustainability thresholds remain open decisions.</p></article></template>
<template v-else-if="section==='platform'"><article class="card"><h2>Operational metadata only</h2><p>No customer impersonation, organization switch bypass or document browser is provided. Platform administrators require ordinary membership and file grants for any document access.</p><DataPanel :data="data"/></article></template>
<template v-else><div class="module-grid"><article class="card"><span class="eyebrow">PHASE 1 · CURRENT</span><h2>Secure foundation</h2><p>Real accounts, workspaces, private documents, versioning, permissions, notes, invitations and audit history.</p><p>Use fictional samples only. For email verification, reset links and invitations, open the local mail catcher configured by your administrator.</p></article><article class="card"><span class="eyebrow">PHASE 2 · NOT CONNECTED</span><h2>Bank statement analysis</h2><p>Extraction, transfer tracing, deterministic income, NSF/overdraft metrics, sustainability, integrity analysis and workbook exports.</p></article><article class="card"><span class="eyebrow">PHASE 3 · NOT CONNECTED</span><h2>Appraisal & rental analysis</h2><p>Lease extraction, photo review, approved guidelines, real DSCR/LTV workflows, revisions and report release testing.</p></article></div><article class="card"><h2>Review walkthrough</h2><ol><li>Create a fictional borrower and demo loan file.</li><li>Upload a fictional PDF/image, or load the separate sample analysis.</li><li>Invite an authorized team member and share only the intended file.</li><li>Open each module. Review a sample finding beside its original source.</li><li>Preview the role-scoped sample report. Revoke a share and verify subsequent requests fail.</li></ol><p>Broker accounts cannot access integrity, fraud, sustainability, internal notes or restricted audit details, and cannot classify or override results.</p></article></template></section></template>
